   880	// Validation
   881	// ============================================
   882	
   883	/**
   884	 * Inspect a SELECT/WITH query's top-level projection and report whether it
   885	 * surfaces an `id` column.
   886	 *
   887	 * Automation-mode content aggregation keys every row by `row.id` (see
   888	 * queryContentData in get_content.ts) and the signed window_token only carries
   889	 * those numeric ids. A source query that omits `id` (e.g. `SELECT origin_id,
   890	 * payload_text FROM events`) therefore produces zero content_ids — which makes
   891	 * complete_window silently report `content_linked: 0` and skip the reaction
   892	 * even though the agent received the rows. We catch that at save time instead.
   893	 *
   894	 * A projection "has id" if it contains a `*` star (bare or table-qualified),
   895	 * a bare `id` column reference, or any column aliased `AS id`.
   896	 *
   897	 * Returns true on any parse failure: this is a best-effort guard, not a
   898	 * security control, and we never want a parser edge case to block a save.
   899	 */
   900	export function queryProjectsIdColumn(query: string): boolean {
   901	  try {
   902	    const root = parseRoot(query);
   903	    // Treat any shape we can't analyze (parse failure, non-SELECT) as "has id"
   904	    // so we never block a save on a parser edge case.
   905	    if (!root || ast.getExprType(root) !== 'select') return true;
   906	    const projection = (ast.getExprData(root) as { expressions?: unknown[] }).expressions;
   907	    if (!Array.isArray(projection)) return true;
   908	
   909	    for (const item of projection as SqlNode[]) {
   910	      const itemType = ast.getExprType(item);
   911	      // Star projection: `*` or `alias.*`
   912	      if (itemType === 'star' || ast.isStar?.(item)) return true;
   913	      if (itemType === 'alias') {
   914	        const d = ast.getExprData(item) as Record<string, unknown>;
   915	        if (identName(d.alias)?.toLowerCase() === 'id') return true; // ... AS id
   916	        const inner = (d.this ?? d.expr) as SqlNode | undefined;
   917	        if (inner && (ast.getExprType(inner) === 'star' || ast.isStar?.(inner))) return true;
   918	      } else if (itemType === 'column') {
   919	        if (identName((ast.getExprData(item) as Record<string, unknown>).name)?.toLowerCase() === 'id')
   920	          return true; // bare `id`
   921	      }
   922	    }
   923	    return false;
   924	  } catch {
   925	    return true;
   926	  }
   927	}
   928	
   929	/**
   930	 * Validate a data source query.
   931	 * Checks: SELECT/WITH prefix, forbidden ops, SQL syntax, schema-qualified refs.
   932	 * When `parse` is true (save-time), also validates syntax and table refs.
   933	 */
   934	export function validateDataSourceQuery(name: string, query: string, parse = false): void {
   935	  const trimmed = query.trim();
   936	  if (!/^(SELECT|WITH)\b/i.test(trimmed)) {
   937	    throw new Error(`Data source '${name}': query must start with SELECT or WITH`);
   938	  }
   939	  if (FORBIDDEN_OPS.test(trimmed)) {
   940	    throw new Error(`Data source '${name}': query contains forbidden operations`);
   941	  }
   942	  if (parse) {
   943	    try {
   944	      const res = parseSql(stripPlaceholders(trimmed), Dialect.PostgreSQL);
   945	      if (!res.success) throw new Error(res.error ?? 'could not parse query');
   946	      // Reject auth/identity tables at save time so a template that would only
   947	      // be masked at runtime fails fast with a clear error. (Runtime masking via
   948	      // SAFE_COLUMN_DEFS is the enforcement; this is early, defense-in-depth
   949	      // feedback.) Column-level allowlisting is intentionally NOT applied here —
   950	      // data sources legitimately reference entity-type slugs (unknown tables).
   951	      const refs = extractTableRefs(trimmed);
   952	      const restricted = refs.filter((t) => ADMIN_ONLY_QUERYABLE_TABLES.has(t));
   953	      if (restricted.length > 0) {
   954	        throw new Error(
   955	          `references admin-only table(s): ${[...new Set(restricted)].join(', ')}`
   956	        );
   957	      }
   958	    } catch (err) {
   959	      throw new Error(`Data source '${name}': ${getErrorMessage(err)}`);
   960	    }
   961	  }
   962	}
   963	
   964	/** Normalize DataSourceInput to entries array */
   965	function toEntries(input: DataSourceInput): Array<[string, string]> {
   360	      suggested_virtual_feeds: suggested,
   361	      more_available: rows.length > MAX_SUGGESTED_VIRTUAL_FEEDS,
   362	      suggested_execution: {
   363	        tool: 'query_sdk',
   364	        method: 'client.feeds.readMany',
   365	        latency_note:
   366	          'Live feed reads are network-bound; run independent feeds in parallel and keep per-feed limits small.',
   367	        example: querySdkExample(suggested),
