   376	export const querySql = withValidatedArgs('query_sql', QuerySqlSchema, querySqlImpl);
   377	
   378	export async function querySqlImpl(
   379	  args: QuerySqlArgs,
   380	  _env: unknown,
   381	  ctx: ToolContext
   382	): Promise<QuerySqlResult> {
   383	  const startTime = Date.now();
   384	  const title = args.title?.trim() || undefined;
   385	  const fail = (message: string, code?: ToolErrorCode): QuerySqlResult => ({
   386	    ...(title ? { title } : {}),
   387	    ...errorResult(message, startTime, code),
   388	  });
   389	
   390	  const baseSql = (args.sql ?? '').trim();
   391	  // `feed` runs a STORED query, so caller `sql` is optional there; every other
   392	  // path requires it. `sql` is optional at the SCHEMA level (so a feed call needs
   393	  // no dummy sql), so this presence check moved here from the typebox boundary —
   394	  // but it stays a hard REJECT (throw), not a structured { error }, preserving the
   395	  // "missing sql rejects at the tool boundary, naming the field" contract.
   396	  if (!baseSql && !args.feed) {
   397	    throw new ToolUserError('query_sql requires `sql` (or a `feed` to read).', 400, 'VALIDATION');
   398	  }
   399	
   400	  // The base query is wrapped as `SELECT * FROM (<sql>) _t [ORDER BY …] LIMIT …`,
   401	  // so an ORDER BY / LIMIT / window inside the caller's SQL is valid (it sits in
   402	  // the subquery). A derived view's backing_sql commonly has `OVER (ORDER BY …)`.
   403	
   404	  // sort_by is optional: omit it for a view whose columns aren't known upfront.
   405	  if (args.sort_by !== undefined && !COLUMN_NAME_RE.test(args.sort_by)) {
   406	    return fail(`Invalid sort_by column name: ${args.sort_by}`);
   407	  }
   408	
   409	  // search_columns only filters in concert with search_term — passing it alone
   410	  // is a silent no-op on both the internal and external paths, which reads as
   411	  // "a filter was applied" when none was. Reject it so the caller notices.
   412	  if (args.search_columns?.length && !args.search_term) {
   413	    return fail(
   414	      'search_columns has no effect without search_term — set search_term to filter, or drop search_columns.'
   415	    );
   416	  }
   417	
   418	  // Resolve the target organization. By default, the caller's bound org. When
   419	  // `org_slug` is supplied: only OAuth on the unscoped /mcp endpoint may
   420	  // cross-org. The single source of truth is `ctx.allowCrossOrg`, which is
   421	  // computed from `tokenType === 'oauth' && !scopedToOrg`.
   422	  let targetOrgId = ctx.organizationId;
   423	  // Members may query their own org's operational tables; the auth/identity
   424	  // tables stay admin-only (enforced via restrictedTables below).
   425	  let callerIsAdmin = isAdminOrOwnerRole(ctx.memberRole);
   426	  if (args.org_slug) {
