443				id: Number(identity.id),
444				mergedFromEntityId:
445					identity.merged_from_entity_id == null
446						? null
447						: Number(identity.merged_from_entity_id),
448			})),
449			redirectedEntityIds: redirectedIds,
450			relationships: relationshipsBefore.map((before) => {
451				const after = afterById.get(Number(before.id));
452				if (!after)
453					throw new Error(`applyMerge: relationship ${before.id} disappeared`);
454				return {
455					id: Number(before.id),
456					before: {
457						fromEntityId: Number(before.from_entity_id),
458						toEntityId: Number(before.to_entity_id),
459						deletedAt: timestamp(before.deleted_at),
460					},
461					after: {
462						fromEntityId: Number(after.from_entity_id),
463						toEntityId: Number(after.to_entity_id),
464						deletedAt: timestamp(after.deleted_at),
465					},
466				};
467			}),
468		};
469		const resolution = params.resolution ?? { decision: "human" as const };
470		await tx`
471	    INSERT INTO entity_merge_operations
472	      (organization_id, winner_entity_id, loser_entity_id, source_run_id,
473	       automation_id, window_id, decision, policy_hash, evidence, ledger, merged_by)
474	    VALUES
475	      (${orgId}, ${winnerId}, ${loserId}, ${resolution.sourceRunId ?? null},
476	       ${resolution.automationId ?? null}, ${resolution.windowId ?? null},
477	       ${resolution.decision}, ${resolution.policyHash ?? null},
478	       ${tx.json(resolution.evidence ?? [])}, ${tx.json(ledger)}, ${mergedBy})
479	  `;
480	
481	  logger.info(
482	    {
483	      orgId,
484	      loserId,
485	      winnerId,
486	      mergedBy,
487	      movedIdentities: moved.length,
488	      repointedEdges: repointed.length,
489	    },
490			"entity merge applied",
491	  );
492	
493	  return {
494	    movedIdentities: moved.length,
495	    repointedEdges: repointed.length,
496	  };
497	}
