499	export interface ApplyUnmergeParams {
500	  orgId: string;
501	  /** The tombstoned loser to split back out. */
502	  loserId: number;
503	  /** Who triggered the un-merge — for the audit log. */
504	  unmergedBy: string;
505	}
506	
507	export interface ApplyUnmergeResult {
508	  winnerId: number;
509	  /** Identities moved back from the winner to the loser. */
510	  restoredIdentities: number;
511	}
512	
513	/**
514	 * Reverse a merge: split `loser` back out of the winner. The durable operation
515	 * ledger restores moved identities, canonical metadata, field ownership,
516	 * relationship endpoints, and redirects flattened by this operation.
517	 *
518	 * Chains: `applyMerge` FLATTENS, so every tombstoned loser points at the TERMINAL
519	 * winner. In `L→W→V`, undo W→V first; that restores L→W and all identities W
520	 * held before the outer merge. L→W can then be undone exactly. Attempting to
510	  restoredIdentities: number;
511	}
512	
513	/**
514	 * Reverse a merge: split `loser` back out of the winner. The durable operation
515	 * ledger restores moved identities, canonical metadata, field ownership,
516	 * relationship endpoints, and redirects flattened by this operation.
517	 *
518	 * Chains: `applyMerge` FLATTENS, so every tombstoned loser points at the TERMINAL
519	 * winner. In `L→W→V`, undo W→V first; that restores L→W and all identities W
520	 * held before the outer merge. L→W can then be undone exactly. Attempting to
521	 * undo L directly while it points at V fails closed.
522	 */
523	export async function applyUnmerge(
524		params: ApplyUnmergeParams,
525		db: DbClient = getDb(),
526	): Promise<ApplyUnmergeResult> {
527	  const { orgId, loserId, unmergedBy } = params;
528	
529	  return db.begin(async (tx) => {
530	    // Discover the winner WITHOUT locking first: we can't name the winner until
531	    // we read merged_into, but taking the loser's lock here would grab the
532	    // loser's row before the winner's — inverting applyMerge's lowest-id-first
533	    // order and deadlocking a concurrent merge of the same pair whenever
534	    // winnerId < loserId.
535	    const [probe] = (await tx<{ merged_into: number | null }>`
536	      SELECT merged_into
537	      FROM entities
538	      WHERE organization_id = ${orgId} AND id = ${loserId}
539	    `) as Array<{ merged_into: number | null }>;
540	    if (!probe) {
541	      throw new Error(`applyUnmerge: entity ${loserId} not found in org`);
542	    }
543	    if (probe.merged_into === null) {
544				throw new Error(
545					`applyUnmerge: entity ${loserId} is not merged into anything`,
546				);
547	    }
548	    const winnerId = Number(probe.merged_into);
549	
550	    // Lock BOTH rows in one statement, ascending id (matches applyMerge), so no
551	    // path ever holds these two locks in opposing orders.
552			const [lo, hi] =
553				loserId < winnerId ? [loserId, winnerId] : [winnerId, loserId];
554	    const locked = (await tx<{
555	      id: number;
556	      merged_into: number | null;
557				metadata: Record<string, unknown>;
558				field_controls: Record<string, unknown>;
559	    }>`
560	      SELECT id, merged_into, metadata, field_controls
561	      FROM entities
562	      WHERE organization_id = ${orgId} AND id IN (${lo}, ${hi})
563	      ORDER BY id
564	      FOR UPDATE
565	    `) as Array<{
566				id: number;
567				merged_into: number | null;
568				metadata: Record<string, unknown>;
569				field_controls: Record<string, unknown>;
570			}>;
571	
572	    // Re-validate under lock: merged_into can move between the unlocked probe and
573	    // acquiring the lock (a racing unmerge/merge). Fail closed if it changed so
574	    // we never operate on a stale winner we didn't lock.
575	    const loserRow = locked.find((row) => Number(row.id) === loserId);
576	    if (!loserRow) {
577	      throw new Error(`applyUnmerge: entity ${loserId} not found in org`);
578	    }
579	    if (
580	      loserRow.merged_into === null ||
581	      Number(loserRow.merged_into) !== winnerId
582	    ) {
583				throw new Error(
584					`applyUnmerge: entity ${loserId} is not merged into anything`,
585				);
586	    }
587	
588			const [operation] = await tx<{
589				id: number;
590				winner_entity_id: number;
591				ledger: {
592					winner: {
593						metadataBefore: Record<string, unknown>;
594						metadataAfter: Record<string, unknown>;
595						fieldControlsBefore: Record<string, unknown>;
596						fieldControlsAfter: Record<string, unknown>;
597					};
598					identities: Array<{
599						id: number;
600						mergedFromEntityId: number | null;
601					}>;
602					redirectedEntityIds: number[];
603					relationships: Array<{
604						id: number;
605						before: {
606							fromEntityId: number;
607							toEntityId: number;
608							deletedAt: string | null;
609						};
610						after: {
611							fromEntityId: number;
612							toEntityId: number;
613							deletedAt: string | null;
614						};
615					}>;
616				};
617			}>`
618	      SELECT id, winner_entity_id, ledger
619	      FROM entity_merge_operations
620	      WHERE organization_id = ${orgId}
621	        AND loser_entity_id = ${loserId}
622	        AND status = 'active'
623	      ORDER BY id DESC
624	      LIMIT 1
625	      FOR UPDATE
626	    `;
627	
628			if (operation) {
629				if (Number(operation.winner_entity_id) !== winnerId) {
630					throw new Error(
631						"applyUnmerge: a later merge changed the canonical entity; undo that merge first",
632					);
633				}
634				const winnerRow = locked.find((row) => Number(row.id) === winnerId);
635				if (!winnerRow) {
636					throw new Error(`applyUnmerge: winner ${winnerId} not found in org`);
637				}
638				const ledger = operation.ledger;
639				if (
640					!isDeepStrictEqual(
641						winnerRow.metadata ?? {},
642						ledger.winner.metadataAfter,
643					) ||
644					!isDeepStrictEqual(
645						winnerRow.field_controls ?? {},
646						ledger.winner.fieldControlsAfter,
647					)
648				) {
649					throw new Error(
650						"applyUnmerge: canonical attributes changed after this merge; exact undo is unsafe",
651					);
652				}
653	
654				const identityIds = ledger.identities.map((item) => item.id);
655				const currentIdentities =
656					identityIds.length > 0
657						? await tx<{
658								id: number;
659								entity_id: number;
660								merged_from_entity_id: number | null;
661								deleted_at: Date | string | null;
662							}>`
663	            SELECT id, entity_id, merged_from_entity_id, deleted_at
664	            FROM entity_identities
665	            WHERE organization_id = ${orgId}
666	              AND id = ANY(${pgBigintArray(identityIds)}::bigint[])
667	            ORDER BY id
668	            FOR UPDATE
669	          `
670						: [];
671				const currentIdentityById = new Map(
672					currentIdentities.map((row) => [Number(row.id), row]),
673				);
674				for (const item of ledger.identities) {
675					const current = currentIdentityById.get(item.id);
676					const expectedMarker = item.mergedFromEntityId ?? loserId;
677					if (
678						!current ||
679						Number(current.entity_id) !== winnerId ||
680						Number(current.merged_from_entity_id) !== expectedMarker ||
681						current.deleted_at !== null
682					) {
683						throw new Error(
684							`applyUnmerge: identity ${item.id} changed after this merge; exact undo is unsafe`,
685						);
686					}
687				}
688	
689				const relationshipIds = ledger.relationships.map((item) => item.id);
690				const currentRelationships =
691					relationshipIds.length > 0
692						? await tx<{
693								id: number;
694								from_entity_id: number;
695								to_entity_id: number;
696								deleted_at: Date | string | null;
697							}>`
698	            SELECT id, from_entity_id, to_entity_id, deleted_at
699	            FROM entity_relationships
700	            WHERE organization_id = ${orgId}
701	              AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
702	            ORDER BY id
703	            FOR UPDATE
704	          `
705						: [];
706				const currentById = new Map(
707					currentRelationships.map((row) => [Number(row.id), row]),
708				);
709				for (const item of ledger.relationships) {
710					const current = currentById.get(item.id);
711					const currentDeletedAt =
712						current?.deleted_at == null
713							? null
714							: new Date(current.deleted_at).toISOString();
715					if (
716						!current ||
717						Number(current.from_entity_id) !== item.after.fromEntityId ||
718						Number(current.to_entity_id) !== item.after.toEntityId ||
719						currentDeletedAt !== item.after.deletedAt
720					) {
721						throw new Error(
722							`applyUnmerge: relationship ${item.id} changed after this merge; exact undo is unsafe`,
723						);
724					}
725				}
726	
727				for (const item of ledger.relationships) {
728					await tx`
729	          UPDATE entity_relationships
730	          SET from_entity_id = ${item.before.fromEntityId},
731	              to_entity_id = ${item.before.toEntityId},
732	              deleted_at = ${item.before.deletedAt},
733	              updated_at = current_timestamp
734	          WHERE organization_id = ${orgId} AND id = ${item.id}
735	        `;
736				}
737	
738				// Authorization edges on EITHER entity are dropped, not restored.
739				//
740				// The merge moved the loser's identities onto the winner, so any ACL
741				// sync that ran in between resolved the loser's provider identity to
742				// the WINNER and granted the winner access. Splitting them again
743				// leaves that grant pointing at someone the provider never granted it
744				// to. Nothing in the ledger describes those edges — they were created
745				// after the merge — so there is no exact state to restore; the only
746				// answer that cannot invent access is to drop both sides and let the
747				// next sync re-derive from the provider.
748				await withAclPrivilege(tx, async () => {
749					await tx`
750	          UPDATE entity_relationships r
751	          SET deleted_at = current_timestamp, updated_at = current_timestamp
752	          FROM entity_relationship_types rt
753	          WHERE rt.id = r.relationship_type_id
754	            AND (rt.purpose = 'authorization' OR rt.slug = 'member_of')
755	            AND r.organization_id = ${orgId}
756	            AND r.deleted_at IS NULL
757	            AND (
758	              r.from_entity_id IN (${loserId}, ${winnerId})
759	              OR r.to_entity_id IN (${loserId}, ${winnerId})
760	            )
761	        `;
762				});
763	
764				const redirectedEntityIds = ledger.redirectedEntityIds ?? [];
765				if (redirectedEntityIds.length > 0) {
766					const restoredRedirects = await transitionEntityMergeRows({
767						tx,
768						organizationId: orgId,
769						ids: redirectedEntityIds,
770						expectedMergedInto: winnerId,
771						transition: { mergedInto: loserId },
772					});
773					if (restoredRedirects.length !== redirectedEntityIds.length) {
774						throw new Error(
775							"applyUnmerge: a flattened redirect changed after this merge; exact undo is unsafe",
776						);
777					}
778				}
779				const restoredWinnerIds = await transitionEntityMergeRows({
780					tx,
781					organizationId: orgId,
782					ids: [winnerId],
783					expectedMergedInto: null,
784					transition: {
785						metadata: ledger.winner.metadataBefore,
786						fieldControls: ledger.winner.fieldControlsBefore,
787					},
788				});
789				if (restoredWinnerIds.length !== 1) {
790					throw new Error(
791						"applyUnmerge: canonical topology changed after locking; exact undo is unsafe",
792					);
793				}
794			}
795	
796			// 1. Restore every identity this operation moved, including identities an
797			//    inner merge had already placed on the loser. Legacy operations have no
798			//    ledger, so they retain the marker-based single-merge fallback.
799			let restored: Array<{ id: number }>;
800			if (operation) {
801				restored = [];
802				for (const identity of operation.ledger.identities) {
803					const rows = await tx<{ id: number }>`
804	          UPDATE entity_identities
805	          SET entity_id = ${loserId},
806	              merged_from_entity_id = ${identity.mergedFromEntityId},
807	              updated_at = current_timestamp
808	          WHERE organization_id = ${orgId} AND id = ${identity.id}
809	          RETURNING id
810	        `;
811					restored.push(...rows);
812				}
813			} else {
814				restored = (await tx<{ id: number }>`
815	      UPDATE entity_identities
816	      SET entity_id = ${loserId},
817	          merged_from_entity_id = NULL,
818	          updated_at = current_timestamp
819	      WHERE organization_id = ${orgId}
820	        AND entity_id = ${winnerId}
821	        AND merged_from_entity_id = ${loserId}
822	        AND deleted_at IS NULL
823	      RETURNING id
824	    `) as Array<{ id: number }>;
825			}
826	
827			// 2. Un-forward and un-tombstone the loser. Ledger-backed merges restored
828			//    redirects flattened through it above; legacy merges retain the old
829			//    single-row automation because no redirect history exists for them.
830			const revivedIds = await transitionEntityMergeRows({
831				tx,
832				organizationId: orgId,
833				ids: [loserId],
834				expectedMergedInto: winnerId,
835				transition: { mergedInto: null, liveness: "live" },
836			});
837			if (revivedIds.length !== 1) {
838				throw new Error(
839					"applyUnmerge: duplicate topology changed after locking; exact undo is unsafe",
840				);
841			}
842			if (operation) {
843				await tx`
844	        UPDATE entity_merge_operations
845	        SET status = 'undone', undone_at = current_timestamp, undone_by = ${unmergedBy}
846	        WHERE id = ${operation.id}
847	      `;
848			}
849	
850	    logger.info(
851	      {
852	        orgId,
853	        loserId,
854	        winnerId,
855	        unmergedBy,
856	        restoredIdentities: restored.length,
857	      },
858				"entity merge reversed",
859	    );
860	
860	
861	    return {
862	      winnerId,
863	      restoredIdentities: restored.length,
864	    };
865	  });
866	}

