    20	/**
    21	 * System-controlled classification of what a relationship type is FOR.
    22	 *
    23	 * `authorization` marks a type the ACL gates read. It is deliberately not
    24	 * caller-settable: the whole point is that the platform, not a caller or a
    25	 * connector manifest, decides which vocabulary grants access.
    26	 */
    27	export type RelationshipTypePurpose = 'authorization';
    28	export const PURPOSE_AUTHORIZATION: RelationshipTypePurpose = 'authorization';
    29	
    30	/**
    31	 * Slugs the ACL engine owns. Reserved so an org cannot create one for ordinary
    32	 * domain modelling and have `ensureMemberOfType` adopt it into the access path —
    33	 * that statement upserts on (organization_id, slug), so an org-authored row with
    34	 * this slug WOULD be adopted.
    35	 *
    36	 * `purpose` is the durable enforcement boundary. During the staged rollout the
    37	 * mutation guard also checks this reserved slug, because ACL reads trust it
    38	 * before the classification backfill lands.
    39	 */
    40	export function isReservedAuthorizationSlug(slug: string): boolean {
    41	  return slug === 'member_of';
    42	}
    43	
    44	/**
    45	 * Run `fn` with the transaction-local flag the ACL edge trigger requires.
    46	 *
    47	 * Enforcement of "only the ACL syncs write authorization edges" lives in a
    48	 * database trigger, not in call-site checks, because `entity_relationships` has
    49	 * several write paths and guarding a subset only ever means the next writer is
    50	 * the bypass. `source` cannot carry the boundary either: the syncs write
    51	 * `source='feed'`, which is also caller-settable, so a caller-minted edge is
    52	 * byte-identical to a sync-minted one.
    53	 *
    54	 * `set_config(..., true)` is transaction-LOCAL. On a pooled connection a session
    55	 * GUC would leak the privilege to whatever ran next; this cannot.
    56	 *
    57	 * This opens a top-level transaction. A writer that is already inside a
    58	 * transaction uses `withAclPrivilege` instead. The privilege is released
    59	 * explicitly so the grant is bounded by `fn`, not by the rest of the caller's
    60	 * transaction.
    61	 */
    62	export async function withAclEdgeWrite<T>(
    63	  db: DbClient,
    64	  fn: (tx: DbClient) => Promise<T>
    65	): Promise<T> {
    66	  return db.begin((tx: DbClient) => withAclPrivilege(tx, () => fn(tx))) as Promise<T>;
    67	}
    68	
    69	/**
    70	 * Grant the ACL-write privilege for exactly `fn`, inside a transaction the
    71	 * caller already owns.
    72	 *
    73	 * `withAclEdgeWrite` opens its own transaction; this is for a writer that is
    74	 * already mid-transaction and must drop the privilege again before its
    75	 * remaining statements run. Merge is the motivating case: it tombstones
    76	 * authorization edges early and then repoints ordinary ones, and if the flag
    77	 * stayed set for the rest of that transaction the trigger could no longer
    78	 * refuse a repoint of any authorization edge the first statement missed.
    79	 *
    80	 * The reset is best-effort: if `fn` failed with a database error the
    81	 * transaction is already aborted and every later statement — including this
    82	 * one — will fail, so swallowing keeps the caller's original error rather than
    83	 * masking it with `current transaction is aborted`. Nothing leaks in that case
    84	 * because the whole transaction rolls back.
    85	 */
    86	export async function withAclPrivilege<T>(tx: DbClient, fn: () => Promise<T>): Promise<T> {
    87	  await tx`SELECT set_config('lobu.acl_write', 'on', true)`;
    88	  try {
    89	    return await fn();
    90	  } finally {
    91	    await tx`SELECT set_config('lobu.acl_write', 'off', true)`.catch(() => {});
    92	  }
    93	}
    94	
    95	/**
    96	 * Refuse a caller-driven mutation of an authorization-bearing relationship type.
    97	 *
    98	 * Without this, classifying `member_of` would make the ACL gates depend on rows
    99	 * that any caller holding the generic entity-link surface could create or
   100	 * soft-delete — i.e. classification alone would hand out a way to mint or revoke
   101	 * access. Applies to link, update_link, unlink, and the schema lifecycle.
   102	 */
   103	export function assertNotAuthorizationType(
   104	  type: { slug?: string | null; purpose?: string | null },
   105	  action: string
   106	): void {
   107	  if (type.purpose !== PURPOSE_AUTHORIZATION) return;
   108	  throw new ToolUserError(
   109	    `Relationship type '${type.slug ?? 'unknown'}' is authorization-bearing and cannot be modified via ${action}. ` +
   110	      'Access-granting edges are maintained by the connector ACL syncs.',
   111	    403
   112	  );
   113	}
   114	
   115	/**
   116	 * Refuse a caller-driven mutation of an EDGE on an ACL-managed relationship type.
   117	 *
   118	 * Stricter than `assertNotAuthorizationType`: it also refuses the RESERVED slug,
   119	 * not just a classified type. That gap matters for the whole window between the
   120	 * deploy that adds this mechanism and the deploy that backfills `purpose` —
   121	 * during it every live `member_of` row is unclassified while the ACL reads
   122	 * already trust the slug, so a purpose-only guard would leave callers free to
   123	 * mint or revoke grants and the backfill would then bless whatever they left
   124	 * behind. The prod audit showing every live `member_of` edge is sync-authored is
   125	 * only a point-in-time fact; this is what keeps it true until classification.
   126	 *
   127	 * Deliberately NOT applied to the relationship-TYPE surfaces. Configs legitimately
   128	 * declare `member_of` (`examples/personal-agent/lobu.config.ts`) — and must, or
   129	 * prune flags it removed and aborts the apply — so refusing it there would break
   130	 * `lobu apply` today. Declaring a type grants nobody access; creating an EDGE on
   131	 * it does. Before classification lands, `lobu apply` needs to treat an ACL-managed
   132	 * type as platform-owned (skip create/update/prune) instead of erroring.
   133	 */
   134	export function assertNotAclManagedEdge(
   135	  type: { slug?: string | null; purpose?: string | null },
   136	  action: string
   137	): void {
   138	  if (
   139	    type.purpose !== PURPOSE_AUTHORIZATION &&
   140	    !isReservedAuthorizationSlug(type.slug ?? '')
   141	  ) {
   142	    return;
   143	  }
   144	  throw new ToolUserError(
   145	    `Relationship type '${type.slug ?? 'unknown'}' is authorization-bearing and cannot be modified via ${action}. ` +
   146	      'Access-granting edges are maintained by the connector ACL syncs.',
   147	    403
   148	  );
   149	}
   150	
   151	/** Source values used to select edges during reconciliation. */
