   159	/**
   160	 * Read a response body as a stream, counting *bytes* and aborting as soon as
   161	 * the running total exceeds `maxBytes` — before buffering the rest. Decodes to
   162	 * UTF-8 text only after the (bounded) body is in hand. Exported for testing.
   163	 */
   164	export async function readBoundedBody(
   165	  res: Response,
   166	  maxBytes: number,
   167	  onOverflow: () => never
   168	): Promise<string> {
   169	  const reader = res.body?.getReader();
   170	  if (!reader) {
   171	    // No streaming body (rare; e.g. a mock). Fall back to text() + a byte check.
   172	    const text = await res.text();
   173	    if (Buffer.byteLength(text, "utf8") > maxBytes) onOverflow();
   174	    return text;
   175	  }
   176	  const chunks: Uint8Array[] = [];
   177	  let total = 0;
   178	  try {
   179	    for (;;) {
   180	      const { done, value } = await reader.read();
   181	      if (done) break;
   182	      if (value) {
   183	        total += value.byteLength;
   184	        if (total > maxBytes) {
   185	          await reader.cancel().catch(() => undefined);
   186	          onOverflow();
   187	        }
   188	        chunks.push(value);
   189	      }
   190	    }
   191	  } finally {
   192	    try {
   193	      reader.releaseLock?.();
   194	    } catch {
   195	      // already released by cancel() — ignore
   196	    }
   197	  }
   198	  return Buffer.concat(chunks.map((c) => Buffer.from(c))).toString("utf8");
