   207	    let url: URL;
   208	    try {
   209	      url = new URL(def.sourceUrl);
   210	    } catch {
   211	      throw new ValidationError(
   212	        `${def.sourceFile}: connector source_url is not a valid URL: ${def.sourceUrl}`
   213	      );
   214	    }
   215	    if (url.protocol !== "https:") {
   216	      throw new ValidationError(
   217	        `${def.sourceFile}: connector source_url must use https (got ${url.protocol}//): ${def.sourceUrl}`
   218	      );
   219	    }
   220	    const controller = new AbortController();
   221	    // Single timer covering the whole exchange — connect AND body consumption.
   222	    const timer = setTimeout(
   223	      () => controller.abort(),
   224	      CONNECTOR_SOURCE_FETCH_TIMEOUT_MS
   225	    );
   226	    let body: string;
   227	    try {
   228	      let res: Response;
   229	      try {
   230	        res = await fetchImpl(def.sourceUrl, { signal: controller.signal });
   231	      } catch (err) {
   232	        throw new ValidationError(
   233	          `${def.sourceFile}: failed to fetch connector source_url ${def.sourceUrl} — ${err instanceof Error ? err.message : String(err)}`
   234	        );
   235	      }
   236	      if (!res.ok) {
   237	        throw new ValidationError(
   238	          `${def.sourceFile}: connector source_url ${def.sourceUrl} returned HTTP ${res.status} ${res.statusText}`
   239	        );
   240	      }
   241	      const contentType = (res.headers.get("content-type") ?? "").toLowerCase();
   242	      if (
   243	        contentType &&
   244	        !/(text\/|application\/(typescript|javascript|x-typescript|octet-stream))/.test(
   245	          contentType
   246	        )
   247	      ) {
   248	        throw new ValidationError(
   249	          `${def.sourceFile}: connector source_url ${def.sourceUrl} returned unexpected content-type "${contentType}" — expected text/*, application/typescript, or application/javascript`
   250	        );
   251	      }
   252	      try {
   253	        body = await readBoundedBody(res, CONNECTOR_SOURCE_MAX_BYTES, () => {
   254	          throw new ValidationError(
   255	            `${def.sourceFile}: connector source_url ${def.sourceUrl} body exceeds the ${CONNECTOR_SOURCE_MAX_BYTES}-byte cap`
   256	          );
   257	        });
   258	      } catch (err) {
