   261	          `${def.sourceFile}: failed to read connector source_url ${def.sourceUrl} — ${err instanceof Error ? err.message : String(err)}`
   262	        );
   263	      }
   264	    } finally {
   265	      clearTimeout(timer);
   266	    }
   267	    if (!body.trim()) {
   268	      throw new ValidationError(
   269	        `${def.sourceFile}: connector source_url ${def.sourceUrl} returned an empty body`
